import numpy as np

class WavySphere:
    def __init__(self, dim=5):
        self.dim = dim

    def f(self, x):
        # Base quadratic term for convexity
        quadratic = np.sum(x**2)
        # Periodic waviness with decreasing amplitude per dimension
        waviness = 0.0
        for i in range(self.dim):
            waviness += 0.5 * (1 - i/self.dim) * np.cos(5 * x[i])
        return quadratic + waviness

import numpy as np

class WavySphere:
    def __init__(self, dim=5):
        self.dim = dim

    def f(self, x):
        # Spherical component
        sphere = np.sum(x**2)

        # Wavy component with multiple frequencies
        wavy = 0.0
        for i in range(self.dim):
            wavy += np.sin(5 * np.pi * x[i]) + 0.5 * np.sin(10 * np.pi * x[i])

        # Combined function with scaling
        return sphere + 0.1 * wavy

import numpy as np

class WavySphere:
    def __init__(self, dim=5):
        self.dim = dim

    def f(self, x):
        # Base sphere term
        sphere_term = np.sum(x**2)

        # Wavy terms with different frequencies
        wavy_terms = 0.0
        for i in range(self.dim):
            wavy_terms += 0.1 * np.cos(5 * x[i]) + 0.05 * np.cos(10 * x[i])

        return sphere_term + wavy_terms
